mapper.select:
/* 마케팅 프로젝트 목록 조회 marketing.selectMarketingProjectList */ SELECT A.MKT_ID AS MARKETING_PROJECT_ID , A.PROJECT_NM AS PROJECT_NM , A.APPROVER_USER_ID AS APPROVER_USER_ID , (SELECT M.USER_ID FROM TB_MKT_MEMBER M WHERE M.MKT_ID = A.MKT_ID AND M.MANAGE_YN = 'Y' LIMIT 1) AS MANAGER_USER_ID , (SELECT USER_NM FROM TB_USER WHERE USER_ID = A.APPROVER_USER_ID) AS APPROVER_USER_NM , A.ORG_NM AS ORG_NM , A.PROJECT_OVERVIEW AS PROJECT_OVERVIEW , DATE_FORMAT(A.DUE_DT, '%Y-%m-%d') AS DUE_DT , A.STATUS_CD AS STATUS_CD , C.CODE_NM AS STATUS_NM , A.CREATE_USER_ID AS CREATE_USER_ID , (SELECT USER_NM FROM TB_USER WHERE USER_ID = A.CREATE_USER_ID) AS CREATE_USER_NM , (SELECT COUNT(*) FROM TB_MKT_CONTENT T WHERE T.MKT_ID = A.MKT_ID) AS CONTENT_CNT , DATE_FORMAT(A.CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT , A.MODIFY_USER_ID AS MODIFY_USER_ID , DATE_FORMAT(A.MODIFY_DT, '%Y-%m-%d %H:%i:%s') AS MODIFY_DT FROM TB_MKT A LEFT JOIN TB_CODE C ON C.CODE_GRP_ID = 'MK000001' AND C.CODE_ID = A.STATUS_CD WHERE 1 = 1 AND EXISTS ( SELECT 1 FROM TB_MKT_MEMBER B WHERE B.MKT_ID = A.MKT_ID AND B.USER_ID = #{userId} )
AND A.STATUS_CD = #{statusCd}
AND ( A.PROJECT_NM LIKE CONCAT('%', #{keyword}, '%') OR A.ORG_NM LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY
A.CREATE_DT A.DUE_DT COALESCE(A.MODIFY_DT, A.CREATE_DT)
ASC DESC
LIMIT #{limit}
OFFSET #{offset}

mapper.insert:
/* 마케팅 프로젝트 등록 marketing.insertMarketingProject */
INSERT INTO TB_MKT (
    MKT_ID
    , PROJECT_NM
    , APPROVER_USER_ID
    , ORG_NM
    , PROJECT_OVERVIEW
    , DUE_DT
    , STATUS_CD
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{marketingProjectId}
    , #{projectNm}
    , #{approverUserId, jdbcType=VARCHAR}
    , #{orgNm, jdbcType=VARCHAR}
    , #{projectOverview}
    , #{dueDt, jdbcType=TIMESTAMP}
    , #{statusCd}
    , #{createUserId}
    , NOW()
)

mapper.update:
/* 마케팅 프로젝트 수정 marketing.updateMarketingProject */
UPDATE TB_MKT SET
    PROJECT_NM          = #{projectNm}
    , APPROVER_USER_ID   = #{approverUserId, jdbcType=VARCHAR}
    , ORG_NM             = #{orgNm, jdbcType=VARCHAR}
    , PROJECT_OVERVIEW   = #{projectOverview, jdbcType=VARCHAR}
    , DUE_DT             = #{dueDt, jdbcType=TIMESTAMP}

        , STATUS_CD      = #{statusCd}

    , MODIFY_USER_ID     = #{modifyUserId}
    , MODIFY_DT          = NOW()
WHERE MKT_ID = #{marketingProjectId}

mapper.delete:
/* 마케팅 프로젝트 삭제 marketing.deleteMarketingProject */
DELETE FROM TB_MKT
WHERE MKT_ID = #{marketingProjectId}

mapper.select:
/* 프로젝트 멤버 여부 확인 marketing.countMarketingProjectMember */
SELECT COUNT(*)
FROM TB_MKT_MEMBER
WHERE MKT_ID = #{marketingProjectId}
    AND USER_ID = #{userId}

mapper.insert:
/* 프로젝트 멤버 등록 marketing.insertMarketingProjectMember */
INSERT INTO TB_MKT_MEMBER (MKT_MEMBER_ID, MKT_ID, USER_ID, MANAGE_YN, CREATE_USER_ID, CREATE_DT)
VALUES (#{marketingMemberId}, #{marketingProjectId}, #{userId}, 'N', #{createUserId}, NOW())

mapper.update:
/* 프로젝트 관리자 지정 marketing.updateMarketingManager */
UPDATE TB_MKT_MEMBER SET MANAGE_YN = CASE WHEN USER_ID = #{managerUserId} THEN 'Y' ELSE 'N' END,
    MODIFY_USER_ID = #{modifyUserId}, MODIFY_DT = NOW()
WHERE MKT_ID = #{marketingProjectId}

mapper.select:
/* 신규 멤버 사용자 존재 확인 marketing.countExistingUsers */
SELECT COUNT(*) FROM TB_USER WHERE USER_ID IN
#{id}

mapper.insert:
/* 마케팅 파일 등록 marketing.insertMarketingFile */
INSERT INTO TB_MKT_FILE (
    MKT_FILE_ID
    , MKT_ID
    , FILE_PATH
    , FILE_NM
    , FILE_SIZE
    , FILE_TYPE
    , FILE_PURPOSE_CD
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{marketingFileId}
    , #{marketingProjectId, jdbcType=VARCHAR}
    , #{filePath}
    , #{fileNm}
    , #{fileSize}
    , #{fileType}
    , #{filePurposeCd}
    , #{createUserId}
    , NOW()
)

mapper.select:
/* 마케팅 파일 목록 조회 marketing.selectMarketingFileList */ SELECT MKT_FILE_ID AS MARKETING_FILE_ID , MKT_ID AS MARKETING_PROJECT_ID , FILE_PATH AS FILE_PATH , FILE_NM AS FILE_NM , FILE_SIZE AS FILE_SIZE , FILE_TYPE AS FILE_TYPE , FILE_PURPOSE_CD AS FILE_PURPOSE_CD , CREATE_USER_ID AS CREATE_USER_ID , DATE_FORMAT(CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT FROM TB_MKT_FILE WHERE 1 = 1 AND MKT_ID = #{marketingProjectId}
AND FILE_PURPOSE_CD = #{filePurposeCd}
ORDER BY CREATE_DT DESC

mapper.update:
/* 마케팅 첨부파일명 수정 marketing.updateMarketingFile */
UPDATE TB_MKT_FILE SET
    FILE_NM = #{fileNm}, MODIFY_USER_ID = #{modifyUserId}, MODIFY_DT = NOW()
WHERE MKT_FILE_ID = #{marketingFileId}

/* 임시 파일 프로젝트 연결 marketing.attachMarketingFile */
UPDATE TB_MKT_FILE SET MKT_ID = #{marketingProjectId}, MODIFY_USER_ID = #{modifyUserId}, MODIFY_DT = NOW()
WHERE MKT_FILE_ID = #{marketingFileId} AND MKT_ID IS NULL AND CREATE_USER_ID = #{modifyUserId}

mapper.delete:
/* 마케팅 첨부파일 삭제 marketing.deleteMarketingFile */
DELETE FROM TB_MKT_FILE
WHERE MKT_FILE_ID = #{marketingFileId}

mapper.insert:
/* 마케팅 기획서 등록 marketing.insertMarketingPlan */
INSERT INTO TB_MKT_PLAN (MKT_PLAN_ID, PLAN_VERSION,
    MKT_ID
    , GOAL
    , PRODUCT_NM
    , REQUEST_TXT
    , TARGET_NM
    , KEY_MESSAGE
    , RECOMMEND_CHANNELS
    , VISUAL_TXT
    , SECTIONS_JSON
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (#{marketingPlanId}, 1,
    #{marketingProjectId}
    , #{goal}
    , #{productNm}
    , #{requestTxt, jdbcType=VARCHAR}
    , #{targetNm, jdbcType=VARCHAR}
    , #{keyMessage, jdbcType=VARCHAR}
    , #{recommendChannels, jdbcType=VARCHAR}
    , #{visualTxt, jdbcType=VARCHAR}
    , #{sectionsJson, jdbcType=VARCHAR}
    , #{createUserId}
    , NOW()
)

mapper.update:
/* 마케팅 기획서 수정 marketing.updateMarketingPlan */
UPDATE TB_MKT_PLAN SET
    PLAN_VERSION = PLAN_VERSION + 1
    , GOAL = #{goal}
    , PRODUCT_NM            = #{productNm}
    , REQUEST_TXT           = #{requestTxt, jdbcType=VARCHAR}
    , TARGET_NM             = #{targetNm, jdbcType=VARCHAR}
    , KEY_MESSAGE           = #{keyMessage, jdbcType=VARCHAR}
    , RECOMMEND_CHANNELS    = #{recommendChannels, jdbcType=VARCHAR}
    , VISUAL_TXT            = #{visualTxt, jdbcType=VARCHAR}
    , SECTIONS_JSON         = #{sectionsJson, jdbcType=VARCHAR}
    , MODIFY_USER_ID        = #{modifyUserId}
    , MODIFY_DT             = NOW()
WHERE MKT_ID = #{marketingProjectId}

mapper.select:
/* 마케팅 콘텐츠 목록 조회 marketing.selectMarketingList */ SELECT A.MKT_CONTENT_ID AS MKT_CONTENT_ID , A.MKT_ID AS MARKETING_PROJECT_ID , A.AGENT_ID AS AGENT_ID , A.TITLE AS TITLE , A.OUTPUT_MODE AS OUTPUT_MODE , A.STATUS_CD AS STATUS_CD , C.CODE_NM AS STATUS_NM , A.AI_STATUS_CD AS AI_STATUS_CD , D.CODE_NM AS AI_STATUS_NM , A.CONTENT_TYPE AS CONTENT_TYPE , A.REQUEST_JSON AS REQUEST_JSON , A.VARIANT_COUNT AS VARIANT_COUNT , A.CREATE_USER_ID AS CREATE_USER_ID , A.SELECTED_VARIANT_NO AS SELECTED_VARIANT_NO , A.CONTENT_VERSION AS CONTENT_VERSION , CASE WHEN A.PUBLISH_SCHEDULED_DT IS NOT NULL AND A.STATUS_CD IN ('005','006','007') THEN 'SCHEDULE' WHEN A.STATUS_CD IN ('006','007') THEN 'NOW' ELSE 'HOLD' END AS PUBLISH_TYPE_CD , A.ALERT_HOUR AS ALERT_HOUR , DATE_FORMAT(A.PUBLISH_SCHEDULED_DT, '%Y-%m-%d %H:%i:%s') AS PUBLISH_SCHEDULED_DT , CASE WHEN A.STATUS_CD = '006' THEN 'Y' ELSE 'N' END AS PUBLISHED_YN , B.USER_NM AS CREATE_USER_NM , DATE_FORMAT(A.CREATE_DT, '%Y-%m-%d %H:%i:%s') AS CREATE_DT FROM TB_MKT_CONTENT A LEFT JOIN TB_USER B ON B.USER_ID = A.CREATE_USER_ID LEFT JOIN TB_CODE C ON C.CODE_GRP_ID = 'MK000001' AND C.CODE_ID = A.STATUS_CD LEFT JOIN TB_CODE D ON D.CODE_GRP_ID = 'MK000002' AND D.CODE_ID = A.AI_STATUS_CD WHERE 1 = 1 AND A.MKT_ID = #{marketingProjectId}
AND A.STATUS_CD = #{statusCd}
AND A.TITLE LIKE CONCAT('%', #{keyword}, '%')
AND A.CONTENT_TYPE = #{contentType}
AND A.OUTPUT_MODE = #{outputMode}
AND A.CREATE_DT >= DATE_SUB(NOW(), INTERVAL #{periodDays} DAY)
ORDER BY COALESCE(A.MODIFY_DT, A.CREATE_DT) DESC, A.CREATE_DT DESC

mapper.insert:
/* 마케팅 콘텐츠 등록 marketing.insertMarketing */
INSERT INTO TB_MKT_CONTENT (
    MKT_CONTENT_ID
    , MKT_ID
    , AGENT_ID
    , TITLE
    , OUTPUT_MODE
    , STATUS_CD
    , AI_STATUS_CD
    , CONTENT_TYPE
    , VARIANT_COUNT
    , CONTENT_VERSION
    , REQUEST_JSON
    , CREATE_USER_ID
    , MODIFY_USER_ID
    , CREATE_DT
) VALUES (
    #{mktContentId}
    , #{marketingProjectId}
    , #{agentId}
    , #{title}
    , #{outputMode}
    , #{statusCd}
    , #{aiStatusCd}
    , #{contentType}
    , #{variantCount}
    , 1
    , #{requestJson, jdbcType=LONGVARCHAR}
    , #{createUserId}
    , #{modifyUserId}
    , NOW()
)

mapper.update:
/* 생성 조건과 호출 기록 저장 marketing.updateMarketingRequestJson */
UPDATE TB_MKT_CONTENT SET REQUEST_JSON = #{requestJson, jdbcType=LONGVARCHAR},
    GENERATION_SNAPSHOT_JSON = #{generationSnapshotJson, jdbcType=LONGVARCHAR},
    MODIFY_USER_ID = #{modifyUserId}, MODIFY_DT = NOW()
WHERE MKT_CONTENT_ID = #{mktContentId}

/* 마케팅 콘텐츠 제목 수정 marketing.updateMarketingTitle */
UPDATE TB_MKT_CONTENT SET
    TITLE               = #{title}
    , MODIFY_USER_ID    = #{modifyUserId}
    , MODIFY_DT         = NOW()
WHERE MKT_CONTENT_ID = #{mktContentId}

/* 마케팅 콘텐츠 상태 수정 marketing.updateMarketingStatus */
UPDATE TB_MKT_CONTENT SET
    STATUS_CD           = #{statusCd}
    , MODIFY_USER_ID    = #{modifyUserId}
    , MODIFY_DT         = NOW()
WHERE MKT_CONTENT_ID = #{mktContentId}

/* 마케팅 콘텐츠 생성 처리 상태 수정 marketing.updateMarketingAiStatus */
UPDATE TB_MKT_CONTENT SET
    AI_STATUS_CD       = #{aiStatusCd}
    , MODIFY_USER_ID    = #{modifyUserId}
    , MODIFY_DT         = NOW()
WHERE MKT_CONTENT_ID = #{mktContentId}

/* 생성 결과 상태 저장 marketing.completeMarketingGeneration */
UPDATE TB_MKT_CONTENT SET AI_STATUS_CD = #{aiStatusCd}, STATUS_CD = #{statusCd},
    SELECTED_VARIANT_NO = #{selectedVariantNo, jdbcType=INTEGER}, MODIFY_USER_ID = #{modifyUserId}, MODIFY_DT = NOW()
WHERE MKT_CONTENT_ID = #{mktContentId}

mapper.insert:
/* 마케팅 콘텐츠 시안 등록 marketing.insertMarketingContent */
INSERT INTO TB_MKT_CONTENT_VARIANT (
    MKT_CONTENT_VARIANT_ID
    , MKT_CONTENT_ID
    , VARIANT_NO
    , RECOMMEND_YN
    , CONTENT_LABEL
    , TEXT_PROMPT_JSON
    , IMAGE_PROMPT_JSON
    , TEXT_CONTENT
    , IMAGE_FILE
    , CREATE_USER_ID
    , CREATE_DT
) VALUES (
    #{mktContentVariantId}
    , #{mktContentId}
    , #{variantNo}
    , #{recommendYn}
    , #{contentLabel, jdbcType=VARCHAR}
    , #{textPromptJson, jdbcType=LONGVARCHAR}
    , #{imagePromptJson, jdbcType=LONGVARCHAR}
    , #{textContent, jdbcType=LONGVARCHAR}
    , #{imageFile, jdbcType=LONGVARCHAR}
    , #{createUserId}
    , NOW()
)

mapper.update:
/* 마케팅 콘텐츠 시안 수정(수정된 필드와 프롬프트 직전 값 백업) marketing.updateMarketingContent */
UPDATE TB_MKT_CONTENT_VARIANT SET
    MODIFY_USER_ID     = #{modifyUserId}
    , MODIFY_DT        = NOW()

        , PREV_TEXT_CONTENT = TEXT_CONTENT
        , TEXT_CONTENT      = #{textContent, jdbcType=LONGVARCHAR}
        , PREV_TEXT_PROMPT_JSON = TEXT_PROMPT_JSON
        , TEXT_PROMPT_JSON = #{textPromptJson, jdbcType=LONGVARCHAR}


        , PREV_IMAGE_FILE   = IMAGE_FILE
        , IMAGE_FILE        = #{imageFile, jdbcType=LONGVARCHAR}
        , PREV_IMAGE_PROMPT_JSON = IMAGE_PROMPT_JSON
        , IMAGE_PROMPT_JSON = #{imagePromptJson, jdbcType=LONGVARCHAR}

WHERE MKT_CONTENT_VARIANT_ID = #{mktContentVariantId}
    AND MKT_CONTENT_ID = #{mktContentId}

mapper.delete:
/* 프로젝트 소속 콘텐츠 시안 전체 삭제 marketing.deleteMarketingContentsByProject */
DELETE FROM TB_MKT_CONTENT_VARIANT
WHERE MKT_CONTENT_ID IN (SELECT MKT_CONTENT_ID FROM TB_MKT_CONTENT WHERE MKT_ID = #{marketingProjectId})
